mapper.sql:
WHERE c.deleted = FALSE

    AND (c.course_no ILIKE #{q.keywordLike} ESCAPE '\'
      OR c.course_name ILIKE #{q.keywordLike} ESCAPE '\'
      OR c.summary ILIKE #{q.keywordLike} ESCAPE '\')


    AND c.review_track = #{q.reviewTrack}


    AND c.domain_code = #{q.domainCode}


    AND c.main_state = #{q.mainState}



    AND (c.dev_state = #{q.subState}
      OR c.selfcheck_state = #{q.subState}
      OR c.trial_state = #{q.subState}
      OR c.publish_state = #{q.subState})


    AND c.owner_no = #{q.ownerNo}



    AND c.quality_marks @> to_jsonb(#{q.qualityMark}::TEXT)


    AND () = #{q.validityStatus}


    AND c.initiated_date >= #{q.initiatedFrom}


    AND c.initiated_date <= #{q.initiatedTo}


    AND c.expect_publish_date >= #{q.expectPublishFrom}


    AND c.expect_publish_date <= #{q.expectPublishTo}


    AND calc_light(
          c.expect_publish_date,
          c.last_state_changed_at,
          (SELECT t.blue_days FROM cfg_warning_threshold t
            WHERE t.object_type = '课程' AND t.deleted = FALSE),
          (SELECT t.red_days FROM cfg_warning_threshold t
            WHERE t.object_type = '课程' AND t.deleted = FALSE),
          c.main_state IN ('已关闭', '课程归档', '案例归档')
        ) = #{q.light}




            AND EXISTS (SELECT 1 FROM rel_demand_course rc WHERE rc.course_id = c.id)


            AND NOT EXISTS (SELECT 1 FROM rel_demand_course rc WHERE rc.course_id = c.id)
